def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    prev_value = 0

    for char in s:
        current_value = values[char]

        if current_value > prev_value:
            result -= 2 * prev_value

        result += current_value
        prev_value = current_value

    if len(s) == 0 or not all(char.isupper() for char in s):
        return None

    return result
