def rle_encode(s):
    if not s:
        return ''
    encoded = ''
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            encoded += current_char + str(count)
            current_char = char
            count = 1
    encoded += current_char + str(count)
    return encoded

